package com.jinloes.practice;
import java.util.*;
public class Solution { private record S(int w,int i){} private record B(long t,int w,int i){} public static int[] assignTasks(int[] serverWeights,int[] taskDurations){ PriorityQueue<S> idle=new PriorityQueue<>((a,b)->a.w!=b.w?Integer.compare(a.w,b.w):Integer.compare(a.i,b.i)); PriorityQueue<B> busy=new PriorityQueue<>((a,b)->a.t!=b.t?Long.compare(a.t,b.t):a.w!=b.w?Integer.compare(a.w,b.w):Integer.compare(a.i,b.i)); for(int i=0;i<serverWeights.length;i++)idle.add(new S(serverWeights[i],i)); int[] ans=new int[taskDurations.length]; long time=0; for(int task=0;task<taskDurations.length;task++){ time=Math.max(time,task); if(idle.isEmpty()&&!busy.isEmpty())time=Math.max(time,busy.peek().t); while(!busy.isEmpty()&&busy.peek().t<=time){B b=busy.remove(); idle.add(new S(b.w,b.i));} S s=idle.remove(); ans[task]=s.i; busy.add(new B(time+taskDurations[task],s.w,s.i)); } return ans; } }
